USE MiProyectoDb;
GO
SET NOCOUNT ON;

CREATE TABLE #WorkoutGuideExercises (
    Nombre NVARCHAR(100) NOT NULL,
    Descripcion NVARCHAR(500) NULL,
    GrupoMuscular NVARCHAR(50) NOT NULL,
    MusculoPrincipal NVARCHAR(50) NOT NULL,
    MusculosSecundarios NVARCHAR(500) NOT NULL,
    Slug NVARCHAR(100) NOT NULL,
    Equipamiento NVARCHAR(50) NOT NULL,
    TipoEjercicio NVARCHAR(50) NOT NULL,
    EsEstiramiento BIT NOT NULL
);


MERGE dbo.Ejercicio AS Target
USING #WorkoutGuideExercises AS Source
    ON Target.Slug = Source.Slug
WHEN MATCHED THEN
    UPDATE SET
        Target.Nombre = Source.Nombre,
        Target.Descripcion = Source.Descripcion,
        Target.GrupoMuscular = Source.GrupoMuscular,
        Target.MusculoPrincipal = Source.MusculoPrincipal,
        Target.MusculosSecundarios = Source.MusculosSecundarios,
        Target.Equipamiento = Source.Equipamiento,
        Target.TipoEjercicio = Source.TipoEjercicio,
        Target.EsEstiramiento = Source.EsEstiramiento
WHEN NOT MATCHED THEN
    INSERT (Nombre, Descripcion, GrupoMuscular, MusculoPrincipal, MusculosSecundarios, Slug, Equipamiento, TipoEjercicio, EsEstiramiento)
    VALUES (Source.Nombre, Source.Descripcion, Source.GrupoMuscular, Source.MusculoPrincipal, Source.MusculosSecundarios, Source.Slug, Source.Equipamiento, Source.TipoEjercicio, Source.EsEstiramiento);

DECLARE @LegacyExerciseMap TABLE (LegacySlug NVARCHAR(100), SourceSlug NVARCHAR(100));

UPDATE s
SET IdEjercicio = SourceExercise.IdEjercicio
FROM dbo.Serie s
INNER JOIN dbo.Ejercicio LegacyExercise ON LegacyExercise.IdEjercicio = s.IdEjercicio
INNER JOIN @LegacyExerciseMap Mapping ON Mapping.LegacySlug = LegacyExercise.Slug
INNER JOIN dbo.Ejercicio SourceExercise ON SourceExercise.Slug = Mapping.SourceSlug;

DELETE LegacyRoutineExercise
FROM dbo.RutinaEjercicio LegacyRoutineExercise
INNER JOIN dbo.Ejercicio LegacyExercise ON LegacyExercise.IdEjercicio = LegacyRoutineExercise.IdEjercicio
INNER JOIN @LegacyExerciseMap Mapping ON Mapping.LegacySlug = LegacyExercise.Slug
INNER JOIN dbo.Ejercicio SourceExercise ON SourceExercise.Slug = Mapping.SourceSlug
WHERE EXISTS (
    SELECT 1
    FROM dbo.RutinaEjercicio SourceRoutineExercise
    WHERE SourceRoutineExercise.IdRutina = LegacyRoutineExercise.IdRutina
      AND SourceRoutineExercise.IdEjercicio = SourceExercise.IdEjercicio
);

UPDATE LegacyRoutineExercise
SET IdEjercicio = SourceExercise.IdEjercicio
FROM dbo.RutinaEjercicio LegacyRoutineExercise
INNER JOIN dbo.Ejercicio LegacyExercise ON LegacyExercise.IdEjercicio = LegacyRoutineExercise.IdEjercicio
INNER JOIN @LegacyExerciseMap Mapping ON Mapping.LegacySlug = LegacyExercise.Slug
INNER JOIN dbo.Ejercicio SourceExercise ON SourceExercise.Slug = Mapping.SourceSlug;

DELETE LegacyExercise
FROM dbo.Ejercicio LegacyExercise
INNER JOIN @LegacyExerciseMap Mapping ON Mapping.LegacySlug = LegacyExercise.Slug;

DROP TABLE #WorkoutGuideExercises;
